import{_ as t,a}from"./chunks/image66.La5G7dGo.js";import{_ as n}from"./chunks/image27.BxJp-sZ3.js";import{_ as o}from"./chunks/image11.B6ai34I9.js";import{_ as i}from"./chunks/image14.X3KdA_b9.js";import{_ as r}from"./chunks/2.BRgDBKom.js";import{_ as s,o as l,c,am as d}from"./chunks/framework.CenUaW7a.js";const h="/projects/AiMechaM1/en/advanced-kit/assets/9.c-ghJ76D.webp",g="/projects/AiMechaM1/en/advanced-kit/assets/image64.CXtDAm7f.png",p="/projects/AiMechaM1/en/advanced-kit/assets/image67.DGSRFcTN.png",m="/projects/AiMechaM1/en/advanced-kit/assets/image68.DPHMOwY0.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image69.Bd2C12m9.png",b="/projects/AiMechaM1/en/advanced-kit/assets/image70.CVofdvsB.png",y="/projects/AiMechaM1/en/advanced-kit/assets/image64.CXtDAm7f.png",P=JSON.parse('{"title":"3.9 Lesson 9: Distance Ranging Sound and Light Alarm","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.9 Lesson 9 Distance Ranging Sound and Light Alarm.md","filePath":"docs/3. Course materials/3.9 Lesson 9 Distance Ranging Sound and Light Alarm.md"}'),f={name:"docs/3. Course materials/3.9 Lesson 9 Distance Ranging Sound and Light Alarm.md"};function w(_,e,v,k,x,z){return l(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="_3-9-lesson-9-distance-ranging-sound-and-light-alarm" tabindex="-1">3.9 Lesson 9: Distance Ranging Sound and Light Alarm <a class="header-anchor" href="#_3-9-lesson-9-distance-ranging-sound-and-light-alarm" aria-label="Permalink to &quot;3.9 Lesson 9: Distance Ranging Sound and Light Alarm&quot;">​</a></h1><h2 id="_3-9-1-lesson-introduction" tabindex="-1">3.9.1 Lesson Introduction <a class="header-anchor" href="#_3-9-1-lesson-introduction" aria-label="Permalink to &quot;3.9.1 Lesson Introduction&quot;">​</a></h2><p>As part of the embodied AI large model curriculum series, this lesson marks a new stage of sensor perception and intelligent interaction. Taking inspiration from supermarket anti-theft systems and automotive parking sensors, ultrasonic distance measurement is introduced to illustrate how robots perceive the environment. Following the path of &quot;sensor principles → single-module testing → conditional judgment → multi-module linkage&quot;, this lesson explains echo ranging and buzzer mechanisms, tests the RGB lights and buzzer, and implements distance-threshold alarms. Combining these features with the Mecanum-wheel car chassis completes an intelligent obstacle avoidance system that &quot;stops and triggers a sound + light alarm upon detecting an obstacle&quot;, laying a solid foundation for dynamic obstacle avoidance.</p><h2 id="_3-9-2-learning-objectives" tabindex="-1">3.9.2 Learning Objectives <a class="header-anchor" href="#_3-9-2-learning-objectives" aria-label="Permalink to &quot;3.9.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the physical characteristics of ultrasonic waves and the working principle of echo distance measurement. Master the correspondence between buzzer pitch and vibration frequency. Learn the three-layer intelligent control architecture of sensing, decision-making, and execution.</p><p><strong>2.</strong> Accurately read real-time distance values from the ultrasonic sensor. Master the commands for buzzer tone playback and volume configuration. Proficiently apply conditional judgment statements to implement distance-threshold triggering logic.</p><p><strong>3.</strong> Establish a robot control thinking framework of &quot;sensing, decision-making, and execution&quot;. Cultivate closed-loop control awareness where sensor data drives robot behavior. Strengthen logical thinking skills in threshold judgment and state switching.</p><p><strong>4.</strong> Connect ultrasonic distance measurement technology to various daily application scenarios, including automotive parking sensors, automatic sensing doors, anti-theft alarms, industrial liquid level detection, and medical ultrasound imaging. Understand the broad application value of distance perception technology in security, industry, healthcare, and smart homes.</p><h2 id="_3-9-3-preparation" tabindex="-1">3.9.3 Preparation <a class="header-anchor" href="#_3-9-3-preparation" aria-label="Permalink to &quot;3.9.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation</strong>:</p><ul><li><p>AiMecha M1 Mecanum-wheel robot base × 1</p></li><li><p>Type-C USB data cable × 1</p></li><li><p>Computer running Windows or macOS × 1</p></li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Ultrasonic Ranging Principle Description</strong>: The ultrasonic module emits ultrasonic pulse signals outward, which reflect back as echoes upon encountering an obstacle. The module measures the time difference between transmission and reception, calculating the distance based on the speed of sound in air at approximately 340 m/s. The calculation formula is Distance = Speed of Sound × Time ÷ 2, where dividing by 2 accounts for the round-trip distance traveled by the sound wave.</p><p><strong>Buzzer Principle Description</strong>: The buzzer generates sound through piezoelectric ceramic vibration, where the pitch is determined by the vibration frequency, and a higher frequency produces a higher pitch. The beat parameter controls the duration of the sound, and under background playback mode, the sound is independently driven by the hardware without blocking the main program.</p><p><strong>Hardware Port Description</strong>: Connect the ultrasonic sensor to port K. The buzzer is an onboard resource requiring no additional wiring.</p><h2 id="_3-9-4-hands-on-project" tabindex="-1">3.9.4 Hands-On Project <a class="header-anchor" href="#_3-9-4-hands-on-project" aria-label="Permalink to &quot;3.9.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project implements an obstacle-triggered sound and light alarm with automatic stopping for the Mecanum-wheel car, adopting a three-layer intelligent control architecture of sensing, decision-making, and execution. The sensing layer relies on the ultrasonic sensor to detect the real-time distance to obstacles ahead. The decision-making layer uses loop polling and conditional judgment to compare the detected distance against a 10 cm safety threshold in real time. The execution layer coordinates the entire robot system to trigger emergency braking, red warning lights, and buzzer alarms. Using a looped dual-branch conditional control logic, the car drives normally when no obstacles are present, immediately sounds the alarm and stops upon detecting a close-range obstacle, and automatically resumes driving once the obstacle is removed, forming a complete closed-loop control system.</p><img loading="lazy" height="540" width="960" src="'+h+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="666" width="672" src="'+g+'" class="common_img" style="width:460px;aspect-ratio:672 / 666;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Sensor reading</td><td style="text-align:center;"><img loading="lazy" height="76" width="414" src="'+t+'" class="common_img" style="width:200px;aspect-ratio:414 / 76;"></td><td style="text-align:left;">Reads the real-time ultrasonic distance measurement value in centimeters.</td></tr><tr><td style="text-align:center;">Buzzer control</td><td style="text-align:center;"><img loading="lazy" height="66" width="594" src="'+a+'" class="common_img" style="width:400px;aspect-ratio:594 / 66;"></td><td style="text-align:left;">Controls the buzzer to play a specified musical note, supporting non-blocking background playback.</td></tr><tr><td style="text-align:center;">Buzzer control</td><td style="text-align:center;"><img loading="lazy" height="100" width="310" src="'+p+'" class="common_img" style="width:150px;aspect-ratio:310 / 100;"></td><td style="text-align:left;">Immediately stops the buzzer from sounding.</td></tr><tr><td style="text-align:center;">Sensor lighting</td><td style="text-align:center;"><img loading="lazy" height="95" width="582" src="'+m+'" class="common_img" style="width:250px;aspect-ratio:582 / 95;"></td><td style="text-align:left;">Sets the onboard RGB LED color of the ultrasonic module.</td></tr><tr><td style="text-align:center;">Motion control</td><td style="text-align:center;"><img loading="lazy" height="90" width="342" src="'+n+'" class="common_img" style="width:200px;aspect-ratio:342 / 90;"></td><td style="text-align:left;">Immediately stops all motors when an obstacle is detected.</td></tr><tr><td style="text-align:center;">Loop control</td><td style="text-align:center;"><img loading="lazy" height="276" width="415" src="'+o+'" class="common_img" style="width:120px;aspect-ratio:415 / 276;"></td><td style="text-align:left;">Continuously checks the distance in a loop for real-time response.</td></tr><tr><td style="text-align:center;">Conditional judgment</td><td style="text-align:center;"><img loading="lazy" height="627" width="589" src="'+i+'" class="common_img" style="width:120px;aspect-ratio:589 / 627;"></td><td style="text-align:left;">Dual-branch judgment block that switches between alarm and normal states.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Sound and Light Module Test</strong></p><ul><li><p>Trigger condition: Start the program when the A key is short-pressed.</p></li><li><p>Play note D3 for a 1/2 beat in background playback mode.</p></li><li><p>Set all RGB LEDs on the ultrasonic sensor to red.</p></li><li><p>Functional purpose: Verify that the buzzer and the ultrasonic RGB light hardware function properly.</p></li></ul><img loading="lazy" height="217" width="762" src="'+u+'" class="common_img" style="width:460px;aspect-ratio:762 / 217;"><p><strong>Task 2: Distance Threshold Alarm</strong></p><ul><li><p>Trigger condition: Run automatically on startup with an outer repeat forever loop.</p></li><li><p>Conditional judgment: Check whether the obstacle distance detected by the ultrasonic sensor is less than 10 cm.</p></li><li><p>True branch: Play note D3 + illuminate the ultrasonic RGB lights in red.</p></li><li><p>False branch: Turn off the buzzer + turn off the ultrasonic RGB lights.</p></li><li><p>Overall outcome: Automatically triggers the sound and light alarm when an obstacle approaches within 10 cm, and returns to a silent state once the obstacle moves away.</p></li></ul><img loading="lazy" height="479" width="677" src="'+b+'" class="common_img" style="width:460px;aspect-ratio:677 / 479;"><p><strong>Task 3: Automatic Stopping and Sound-Light Alarm Upon Encountering Obstacles</strong></p><ul><li><p>Trigger condition: Run automatically on startup with an outer repeat forever loop.</p></li><li><p>Conditional judgment: Check whether the obstacle distance detected by the ultrasonic sensor is less than 10 cm.</p></li><li><p>Alarm branch: Play note D3 + turn on the red light + stop the car + wait 0.5 s.</p></li><li><p>Normal branch: Drive the car forward at low speed + turn off the buzzer + turn off the RGB LEDs + wait 0.5 s.</p></li><li><p>Overall outcome: The car drives forward slowly, immediately brakes and triggers a sound and light alarm when an obstacle enters the 10 cm range, and resumes driving once the obstacle is removed.</p></li></ul><img loading="lazy" height="666" width="672" src="'+y+'" class="common_img" style="width:460px;aspect-ratio:672 / 666;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Distance Measurement Sound and Light Alarm</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to upload the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+r+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-9-5-expansion-and-advancement" tabindex="-1">3.9.5 Expansion and Advancement <a class="header-anchor" href="#_3-9-5-expansion-and-advancement" aria-label="Permalink to &quot;3.9.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Multi-Level Distance Alarm System</strong></p><p>Upgrade the single-level alarm to a three-level graded alarm system. Set distances beyond 30 cm as the safe zone with green lights and a muted buzzer. Set distances between 10 cm and 30 cm as the warning zone with yellow lights and intermittent buzzer beeps. Set distances within 10 cm as the danger zone with red lights, continuous buzzer sounding, and emergency braking. Use multi-layer nested conditionals to create a gradient effect where closer distances produce more urgent alarms, simulating an automotive parking sensor system.</p><p><strong>Project 2: Musical Alarm Melody and Flashing Lights</strong></p><p>Replace the single-tone alarm with a short alarm melody composed of multiple musical notes, and change the steady red light to alternating red and blue flashing lights. Combine multiple tone commands sequentially into a musical phrase and alternate light colors to create a flashing effect, making the alarm more noticeable while practicing multi-command sequential arrangement and timing control.</p><h2 id="_3-9-6-q-a" tabindex="-1">3.9.6 Q&amp;A <a class="header-anchor" href="#_3-9-6-q-a" aria-label="Permalink to &quot;3.9.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Why is the ultrasonic distance calculation formula divided by 2?</strong></p><p><strong>Answer</strong>: Dividing by 2 accounts for the complete round-trip path traveled by the ultrasonic wave. The wave is emitted from the transmitter, reflects off an obstacle, and is captured by the receiver, meaning the sound wave travels twice the actual distance to the obstacle during that time interval.</p><p><strong>Q2: Why must a repeat loop be added to the program instead of judging the condition only once?</strong></p><p><strong>Answer</strong>: Judging the condition only once checks the distance a single time at startup before terminating the program, leaving the car unresponsive to any subsequent approaching obstacles and defeating the purpose of real-time monitoring. Adding a Repeat Forever loop ensures &quot;continuous distance monitoring and real-time response&quot;.</p><h2 id="_3-9-7-technical-support-and-discussion" tabindex="-1">3.9.7 Technical Support and Discussion <a class="header-anchor" href="#_3-9-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.9.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',50)])])}const L=s(f,[["render",w]]);export{P as __pageData,L as default};
